#!/usr/bin/env node
/**
 * JS Bundle Budget Checker — Severinno
 *
 * Enforces a JavaScript size budget on the client bundle to prevent
 * regressions from sneaking into production. Parses the @next/bundle-analyzer
 * report (`.next/analyze/client.html`) generated by:
 *
 *     ANALYZE=true pnpm exec next build --webpack
 *
 * Checks:
 *   1. Initial JS of `/` (rootMainFiles from build-manifest.json, gzipped)
 *   2. Total client bundle (gzipped)
 *   3. Largest single chunk (gzipped)
 *   4. Per-library sizes: maplibre-gl, recharts, framer-motion, socket.io-client
 *
 * Usage:
 *   node scripts/check-js-budget.mjs            # fail CI if over budget
 *   node scripts/check-js-budget.mjs --report   # print details, no failure
 *   node scripts/check-js-budget.mjs --update   # print suggested budgets (+20% headroom)
 *
 * Budgets can be overridden via env vars (KB, gzip):
 *   JS_BUDGET_INITIAL_KB=150 JS_BUDGET_TOTAL_KB=1400 ...
 */

import fs from "node:fs"
import path from "node:path"
import zlib from "node:zlib"

const KB = 1024
const ROOT = process.cwd()
const ANALYZE_HTML = path.join(ROOT, ".next", "analyze", "client.html")
const BUILD_MANIFEST = path.join(ROOT, ".next", "build-manifest.json")

// ─── Budgets (KB, gzip) — set from the measured baseline + ~20% headroom ───
const BUDGETS = {
  initialGzipKB: num(process.env.JS_BUDGET_INITIAL_KB, 150),
  totalGzipKB: num(process.env.JS_BUDGET_TOTAL_KB, 1400),
  largestChunkGzipKB: num(process.env.JS_BUDGET_LARGEST_CHUNK_KB, 300),
  libs: {
    "maplibre-gl": { budgetKB: num(process.env.JS_BUDGET_LIB_MAPLIBRE_KB, 300), envKey: "JS_BUDGET_LIB_MAPLIBRE_KB" },
    recharts: { budgetKB: num(process.env.JS_BUDGET_LIB_RECHARTS_KB, 100), envKey: "JS_BUDGET_LIB_RECHARTS_KB" },
    "framer-motion": { budgetKB: num(process.env.JS_BUDGET_LIB_FRAMER_KB, 50), envKey: "JS_BUDGET_LIB_FRAMER_KB" },
    "socket.io-client": { budgetKB: num(process.env.JS_BUDGET_LIB_SOCKETIO_KB, 20), envKey: "JS_BUDGET_LIB_SOCKETIO_KB" },
  },
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function num(raw, fallback) {
  const n = Number(raw)
  return Number.isFinite(n) && n > 0 ? n : fallback
}

/** Extract the `window.chartData = [...]` JSON from the analyzer HTML. */
function extractChartData(html) {
  const marker = "window.chartData = "
  const start = html.indexOf(marker)
  if (start < 0) throw new Error(`"${marker}" not found in ${ANALYZE_HTML}`)
  let i = start + marker.length
  while (i < html.length && /\s/.test(html[i])) i++
  if (html[i] !== "[") throw new Error("chartData is not an array")
  let depth = 0
  let inString = false
  let esc = false
  for (let j = i; j < html.length; j++) {
    const c = html[j]
    if (inString) {
      if (esc) esc = false
      else if (c === "\\") esc = true
      else if (c === '"') inString = false
      continue
    }
    if (c === '"') inString = true
    else if (c === "[") depth++
    else if (c === "]") {
      depth--
      if (depth === 0) return JSON.parse(html.slice(i, j + 1))
    }
  }
  throw new Error("unbalanced chartData array")
}

/** Sum gzip bytes of a library across all chunks, without double counting. */
function libGzip(assets, lib) {
  let total = 0
  for (const asset of assets) {
    // walk the tree; a node that contains the lib but whose parent doesn't
    // is the top-most match for that branch → its size is the exact total
    const stack = [{ node: asset, parentLabel: "" }]
    while (stack.length) {
      const { node, parentLabel } = stack.pop()
      const label = node.label || ""
      const hasLib = label.includes(lib)
      if (hasLib && !parentLabel.includes(lib)) {
        total += node.gzipSize || 0
        continue // descendants are subsets — skip
      }
      for (const g of node.groups || []) stack.push({ node: g, parentLabel: label })
    }
  }
  return total
}

/** Gzip a file's bytes (for rootMainFiles initial-JS computation). */
function gzipBytes(file) {
  const buf = fs.readFileSync(file)
  return zlib.gzipSync(buf, { level: 9 }).length
}

// ─── Collect data ───────────────────────────────────────────────────────────

const results = { checks: [], failures: [] }

function addCheck(name, currentKB, budgetKB) {
  const ok = currentKB <= budgetKB
  results.checks.push({ name, currentKB, budgetKB, ok })
  if (!ok) results.failures.push(`${name}: ${currentKB.toFixed(1)} KB > budget ${budgetKB} KB (gzip)`)
}

if (!fs.existsSync(ANALYZE_HTML)) {
  console.error(
    `❌ Bundle report not found: ${ANALYZE_HTML}\n` +
      `   Run: ANALYZE=true pnpm exec next build --webpack`,
  )
  process.exit(2)
}

const html = fs.readFileSync(ANALYZE_HTML, "utf8")
const data = extractChartData(html)
const assets = data.filter((a) => a.isAsset)

// 1. Total client bundle
const totalGzip = assets.reduce((s, a) => s + (a.gzipSize || 0), 0)
addCheck("Total client bundle", totalGzip / KB, BUDGETS.totalGzipKB)

// 2. Largest single chunk
const largest = assets.reduce((max, a) => Math.max(max, a.gzipSize || 0), 0)
addCheck("Largest chunk", largest / KB, BUDGETS.largestChunkGzipKB)

// 3. Per-library sizes
for (const [lib, cfg] of Object.entries(BUDGETS.libs)) {
  addCheck(`lib: ${lib}`, libGzip(assets, lib) / KB, cfg.budgetKB)
}

// 4. Initial JS of `/` (rootMainFiles, gzipped) — from build-manifest.json
let initialGzip = 0
let initialSkipped = false
if (fs.existsSync(BUILD_MANIFEST)) {
  const manifest = JSON.parse(fs.readFileSync(BUILD_MANIFEST, "utf8"))
  const rootMain = manifest.rootMainFiles || []
  if (rootMain.length === 0) {
    initialSkipped = true
  } else {
    let foundFiles = 0
    for (const f of rootMain) {
      const p = path.join(ROOT, ".next", f)
      if (fs.existsSync(p)) {
        initialGzip += gzipBytes(p)
        foundFiles++
      }
    }
    if (foundFiles === 0) {
      initialSkipped = true // listed but none on disk — avoid silent 0 KB pass
    } else {
      addCheck("Initial JS (/) rootMainFiles", initialGzip / KB, BUDGETS.initialGzipKB)
    }
  }
}
if (!fs.existsSync(BUILD_MANIFEST) || initialSkipped) {
  results.checks.push({ name: "Initial JS (/)", currentKB: 0, budgetKB: 0, ok: true, skipped: true })
}

// ─── Report ─────────────────────────────────────────────────────────────────

const report = process.argv.includes("--report")
const update = process.argv.includes("--update")

console.log("📦 JS Bundle Budget")
console.log("─".repeat(46))
for (const c of results.checks) {
  const mark = c.ok ? "✅" : "❌"
  const skip = c.skipped ? " (skipped — no rootMainFiles / build-manifest.json)" : ""
  console.log(
    `  ${mark} ${c.name.padEnd(28)} ${c.currentKB.toFixed(1).padStart(7)} KB gzip` +
      (c.budgetKB ? `  (budget ${c.budgetKB} KB)` : "") + skip,
  )
}
if (report) {
  console.log("\nℹ️  Measured totals:")
  console.log(`   total gzip:  ${(totalGzip / KB).toFixed(1)} KB (${assets.length} chunks)`)
  console.log(`   largest:     ${(largest / KB).toFixed(1)} KB`)
  console.log(`   initial (/): ${(initialGzip / KB).toFixed(1)} KB`)
}
if (update) {
  // Suggest budgets with ~20% headroom over current measurements
  const suggest = (cur, name) => `${name}: ${Math.ceil((cur * 1.2) / 10) * 10} KB (current ${cur.toFixed(1)} KB)`
  console.log("\n📝 Suggested budgets (current +20% headroom, rounded up to 10 KB):")
  console.log(`   JS_BUDGET_INITIAL_KB           → ${suggest(initialGzip / KB, "initial")}`)
  console.log(`   JS_BUDGET_TOTAL_KB             → ${suggest(totalGzip / KB, "total")}`)
  console.log(`   JS_BUDGET_LARGEST_CHUNK_KB     → ${suggest(largest / KB, "largest chunk")}`)
  for (const [lib, cfg] of Object.entries(BUDGETS.libs)) {
    console.log(`   ${cfg.envKey} → ${suggest(libGzip(assets, lib) / KB, lib)}`)
  }
}

if (results.failures.length) {
  console.error("\n❌ BUDGET VIOLATIONS:")
  for (const f of results.failures) console.error(`   - ${f}`)
  console.error("\nReview new dependencies or lazy-load the offending library.")
  process.exit(1)
}

console.log("\n✅ All JS budgets within limits.")
process.exit(0)
